+package semver
+
+import "testing"
+
+func TestNewConstraintRejectsAdjacentNumbers(t *testing.T) {
+	for _, s := range []string{"12.3.4.1234", "12.23.4.1234", "12.3.34.1234", "12.23.4 1234", "12.3.34 1234"} {
+		if _, err := NewConstraint(s); err == nil {
+			t.Errorf("expected error for %q", s)
+		}
+	}
+}
+
+func TestNewConstraintAcceptsSeparatedForms(t *testing.T) {
+	for _, s := range []string{"1.2.3", "1.2.3,2.0.0", ">=1.2.3 <2.0.0", ">=1.2.3<2.0.0", "2.x, >=1.2.3", "1.2.3,"} {
+		if _, err := NewConstraint(s); err != nil {
+			t.Errorf("unexpected error for %q: %s", s, err)
+		}
+	}
+}
